const fs = require('fs');
const path = require('path');

function stripNikud(text) {
  return text.replace(/[\u0591-\u05BD\u05BF-\u05C7]/g, '');
}

function splitIntoParagraphs(text) {
  // Split on double newlines or significant breaks
  // If no double newlines, treat as single paragraph
  const parts = text.split(/\n\n+/).map(p => p.trim()).filter(p => p.length > 0);
  return parts;
}

function createReaderJson({ id, book, part, torah, displayNumber, title, hebrewTitle, segments, navigation }) {
  return {
    id,
    book: book || 'likutay-moharan',
    part,
    torah,
    displayNumber,
    title,
    hebrewTitle,
    keyVerse: '',
    keyVerseTranslation: '',
    keyVerseRef: '',
    themes: [],
    keywords: [],
    simanim: [],
    segments,
    totalParagraphs: segments.length,
    hasEnglish: false,
    navigation,
    hasNikud: true
  };
}

function makeSegments(nikudText) {
  const paragraphs = splitIntoParagraphs(nikudText);
  return paragraphs.map((p, i) => ({
    index: i + 1,
    he: stripNikud(p),
    en: '',
    he_nikud: p
  }));
}

// ============ SHIR NA'IM ============
const shirNikud = `וְאֵלֶּה דִבְרֵי רַבֵּנוּ זִכְרוֹנוֹ לִבְרָכָה שִׁיר נָעִים כּוֹלֵל עִנְיָנִים רַבִּים בִּדְבָרִים מֻעָטִים מֻעָט מַחֲזִיק הַמְרֻבֶּה יְדַבֵּר נִפְלָאוֹת מִשֶּׁבַח תּוֹרָתֵנוּ הַקְּדוֹשָׁה וּמִשֶּׁבַח משֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם וּמוּסָר נִפְלָא וְהִתְעוֹרְרוּת עָצוּם שֶׁיְּעוֹרֵר כָּל אֶחָד אֶת נַפְשׁוֹ וִידַבֵּר מִגְּדֻלַּת הַבּוֹרֵא יִתְבָּרַךְ וְנִפְלְאוֹת בְּרִיּוֹתָיו וִינַצַּח בְּשִׁירוֹ לְהַזְכִּיר נִפְלְאוֹת עֲרֵבַת נְעִימַת תַּעֲנוּגֵי הָעוֹלָם הַבָּא וְשַׁעֲשׁוּעָיו לְכָל הַזּוֹכִים אֲלֵיהֶם וְהַשִּׁיר שֶׁיִּתְעַר לֶעָתִיד וּלְהֵפֶךְ מְרִירַת הַמַּכְאוֹב וְקַהַיוֹן שִׁנַּיִם שֶׁל הַנִּדָּחִים מֵהֶם וְאוֹבְדִים אֲבֵדָה שֶׁאֵינָהּ חוֹזֶרֶת יְעוֹרֵר יְשֵׁנִים יָקִיץ נִרְדָּמִים יְחַזֵּק עֲיֵפִים יוֹדִיעַ לְהָאָדָם מִגּדֶל כּחוֹ אֲשֶׁר בְּיָדוֹ וְכחוֹ לִזְכּוֹת לְכָל אֵלֶּה כְּשׁוֹפָר יָרִים קוֹלוֹ לְהַטּוֹת לְבָבֵנוּ אֵלָיו יִתְבָּרַךְ לְעָבְדוֹ שְׁכֶם אֶחָד הֵן אֵלֶּה קְצוֹת דַּרְכֵי הַשִּׁיר הַזֶּה.

נִימוּסֵי הַדָּתוֹת כֻּלָּם לא יִשְׁווּ לְדָתֵנוּ חַכְמֵיהֶם בָּדוּ מִלִּבָּם נִימוּסִים בְּשִׂכְלָם הָאֱנוֹשִׁי משֶׁה עָלָה לַמָּרוֹם וְעָנָן לְבוּשׁוֹ נִמְצָא הַמְחֻיָּב דִּבֵּר עִמּוֹ בְּכָל פַּעַם, וּפֵרֵשׁ מִן הָאִשָּׁה נִבְזִים וּדְווּיִים וּסְחוּפִים אֲנַחְנוּ חָכְמָתוֹ מֵאַיִן תִּמָּצֵא, מִמֶּנּוּ לֶקַח טוֹב לָקַחְנוּ מֶלֶךְ בִּישׁוּרוּן עִם דָּתֵנוּ כִּשְׁנֵי אַחִים לא יִתְפָּרְדוּ נִשְׁמָתוֹ וְגוּפוֹ הַזַּךְ, זוֹ מִזּוֹ לא נָדוּ נַפְשׁוֹתָם רַבִּים, כֵּן רַבּוּ דֵּעוֹתֵיהֶם, וְחִלּוּף סְבָרוֹתֵיהֶם חֲדָשִׁים מִקָּרוֹב בָּאוּ עֲבוֹדוֹתֵיהֶם מַחְשְׁבוֹתֵיהֶם לא מַחְשְׁבוֹתֵינוּ, וְלא דְּרָכֵינוּ דַּרְכֵיהֶם נַפְשׁוֹתֵינוּ אַחַת הִיא, וְאֵינָהּ נוֹטָה לְרִבּוּי צַלְמֵיהֶם נַפְשִׁי הַחֲזָקָה וְהַפִּקַּחַת לָמָּה לא חַסְתְּ עָלַיִךְ וְשָׁכַחַתְּ אוֹמֵן הַמְגַדֵּל אוֹתָךְ וְהֶאֱכִילֵךְ מַמְתַּקִּים וְהִלְבִּישֵׁךְ אַרְגָּמָן וְעַתָּה אַתָּה רְמוּסָה בֵּין עִקְּבֵי צאן וּבֵין רַגְלֵי הַתַּאֲווֹת הֶעָבִים וְהַגַּשְׁמִיִּים וְאַתָּה עֵרם וְעֶרְיָה יֵין מִשְׁתַּיִךְ נֶהְפַּךְ לְמִשְׁתֶּה שִׂמְחָתִךְ נֶהְפַּךְ לְמִסְפֶּד וּמֵתָה חֶפְצִי בַּחֲיֵי יִתְבָּרֵךְ קוּם רְנָנִי בַלַּיְלָה בְּגוֹלָה אַתָּה מַר יְבַכָּיוּן (אֵיכָה א) יוֹדֵעַ אָנִי כִּי הַדִּמְעוֹת לֶעָתִיד תְּפוּגָנָה לֹא יוֹעִילוּ עוֹד שׁוּבוּ בָנִים שׁוֹבָבִים רְפוּאָה קדֶם לַמַּכָּה כַּכָּתוּב (יְשַׁעְיָה נ''ז) : בּוֹרֵא נִיב שְׂפָתָיִם שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב אָמַר ה'' וּרְפָאתִיו (עַיֵּן שַׁבָּת ק''ד) בּוֹרֵא נִיב שְׂפָתָיִם, וְשָׁלוֹם שָׁלוֹם, שֶׁהוּא כָּפוּל, עוֹלֶה בְּמִסְפָּר תְּשׁוּבָה (עַיֵּן תִּקּוּנִים י''ח י''ט) מוּסָר הַשֵּׁם תַּקְשִׁיב אָזְנֵךְ (מִשְׁלֵי ב') בְּקוֹלוֹ תִּשְׁמַע שׁוּבוּ בָנִים אוֹי לְמוֹרֵד בַּמָּקוֹם אוֹי לְמוֹרֵד בְּדָתוֹ שִׂמְחָה לָנוּ בִּשְׁבִיל כֹּחַ תּוֹרָתֵנוּ בָּהּ סוֹדוֹת עֲמֻקּוֹת וּרְפוּאוֹת מֵחֳלָאֵי גוּפוֹתֵנוּ מַתִּירָה אֲסוּרִים אַךְ כְּפִי מַעֲשֵׂינוּ גַּלְגַּלֵּי הַנְהָגוֹת הָעוֹלָם וְהַנֶּפֶשׁ בָּהּ כְּלוּלִים מַזָּלוֹת וְכוֹכָבִים, צֵרוּפֵי שֵׁמוֹת הַקְּדוֹשִׁים, כָּל הַטּוֹבוֹת בְּכָל הַדְּרָכִים שֶׁבָּעוֹלָם סְגֻלּוֹת חָכְמוֹת וּבִינוֹת, נְבוּאוֹת, רוּחַ הַקּדֶשׁ, בִּנְקִיּוּתֵנוּ לְהַשִּׂיגָם גּוּפֵנוּ אֵצְלֵנוּ הֵיכָלוֹת מְפֻלָּשׁוֹת גַּם הָאֶבֶן שָׁם יַעֲקב וְהַסֻּלָּם לַעֲלוֹת מַלְאָכִים (עַיֵּן יָלְקוּט בְּרֵאשִׁית רֶמֶז קי''ט) וְיוֹנְקִים מֵעוֹלָמוֹת עֶלְיוֹנִים מִי יְמַלֵּל גְּבוּרוֹת ה' מְשַׁבֵּחַ וּמְקַלֵּס לְאֵין סוֹף מִי מָנָה עֲפַר הַתִּפְאֶרֶת צֶמַח מִזֶּרַע שׁוֹשַׁנִּים חֶסֶד לְאַבְרָהָם גֶּבֶר כְּעֵין הַבְּדלַח מִדּוֹת לָנוּ מַפְתְּחוֹת הַשֶּׁפַע לְמִי שֶׁהִצְטָעֵר אִתָּנוּ נֶאֱמַר וּכְזֹהַר הָרָקִיעַ יַזְהִירוּ שֶׁכְבָר נָפְלוּ דִּמְעוֹתָיו כַּפָּרָה עַל עֲוֹנוֹתָיו זְכוֹר אַהֲבָתְךָ הַיְשָׁנָה נְהָרוֹת נְחָלִים אֲפִיקֵי מַיִם רַבִּים וְיַמִּים גְּדוֹלִים וּקְטַנִּים נִפְלָאִים וּמְשֻׁנִּים בְּצִבְעֵיהֶם וּבְטַעֲמֵיהֶם וּבְטִבְעֵיהֶם חַיּוֹת קְטַנּוֹת וּגְדוֹלוֹת בְּכָל אֶחָד וְאֶחָד אֵין מִסְפָּר לְמִינֵיהֶם מְשַׁבְּחִים וּמְהַלְּלִים כֻּלָּם לְהַשֵּׁם יִתְבָּרַךְ בְּכָל אֵיבְרֵיהֶם מִלִּין יַגִּידוּן תָּמִיד וְלא יְכַחֲשׁוּן מַנְהִיגֵיהֶם נוֹצְצִים אֲבָנִים טוֹבוֹת וּמַרְגָּלִיּוֹת בְּעִמְקֵיהֶם נֶחְבָּא בָּהֶם אוֹרוֹת כְּלֵיהֶם נְשָׁמוֹת הַגְּזוּרִים מִתַּחַת כִּסֵּא כָּבוֹד נִכְסְפָה תָּמִיד אֶל שָׁרְשָׁהּ לִהְיוֹת לָבוּד חַיִּים וָחֶסֶד שׁוֹאֶבֶת מֵחַסְדֵּי דָּוִד חֵן רוּחַ מִטִּפֵּי גַּן עֵדֶן מִמֶּנָּה לא אָבַד מוֹשְׁבוֹת הַהֵיכָלוֹת וְאָהֳלֵי הַשָּׁלוֹם לְכָל אַחַת וְאַחַת נִסְמַן וְנִתְוָה תָּיו הוֹד מַה פָּעַל אֵל הַמַּלְאָכִים יִשְׁאֲלוּ, וִירוּצוּן בִּשְׁלִיחוּתָם כְּכוֹכְבָא דְּשָׁבִיט מְרֻחָקִים וּמְסֻלָּקִים מִכָּל הַתַּעֲנוּגִים, מִי שֶׁאָרְחוֹתָיו עָבִיט [מִלְּשׁוֹן וְלא יְעַבְּטוּן ארְחוֹתָם (עַיֵּן רַשִׁ''י יוֹאֵל ב) ] נִשְׁאָרִים בִּשְׁלֵמוּתָם לְכוּ חֲזוּ מִפְעֲלוֹת ה' הָעוֹלָמוֹת כֻּלָּם נִמְשָׁכוֹת מֵאוֹתִיוֹת הַתּוֹרָה מֵאוֹת א' עַד אוֹת ת' בְּצֵרוּפֵיהֶם וּבְחִלּוּפֵיהֶם וּבְגִלְגּוּלֵיהֶם בְּאַתְבַּ''שׁ בְּאַלְבָּ''ם (עַיֵּן שָׁם, וּבְתִקּוּן כא וּבְתִקּוּן ע)

חוֹבְטִים כִּבְמַקְלוֹת בְּצוּרוֹתָם הַמְשֻׁנּוֹת חוֹבְרֵי חֲבָרִים וּמְכַשְּׁפִים מַכְרִיעִים אוֹתָם בְּהַשְׁבָּעָתָם בַּשֵּׁמוֹת הַמְכֻוָּנוֹת הַתּוֹרָה הַקְּדוֹשָׁה שׁוֹמֶרֶת אוֹתָנוּ מִכָּל טֻמְאוֹת הַצְּדָקָה מַצֶּלֶת מִמִּיתוֹת מְגֻנּוֹת נְבוּאָה אֵין לָנוּ חֲרִיקַת שֵׁן הָאֻמּוֹת עַל אֻמָּה יְחִידָה, תְּבוּנָה אֵין בָּנוּ מְרִירַת הַצָּרוֹת אֵיךְ לְהַשְׁקוֹת הֵם דָּנוּ נִסְבּל עוֹלָם עַד יָבוֹא עָנִי בֵּן יְחַפֵּשֹ בְּגִנְזֵי אָבִיו נֵזֶר עֲטֶרֶת נְעַטֵּר בְּבֵן חָבִיב שִׁיר חָדָשׁ אָז נָשִׁיר מַלְכֵּנוּ כָּל אֶחָד וְאֶחָד מַרְאֶה בְּאֶצְבַּע בָּשָׂר חָתוּם תּוֹרָה בְּלֵב כָּל אֶחָד מִלְּהִשָּׁכֵחַ הַמָּוֶת לָנֶצַח יְבֻלַּע כִּקְטרֶת רֵיחַ נָבִיא לְבַב חָכְמָה לְהָבִין תְּכוּנַת גּוּפֵנוּ וּמֶרְחַקֵּי פְּרָקָיו וַעֲרִיכוּת אֵיבָרָיו חִיּוּב הֲבָנָתוֹ מוֹעִילָה לִידִיעַת הַבּוֹרֵא הַמְצַיֵּר אֵלּוּ הַיְצִירוֹת כֻּלָּם מְרַפֵּא כָּל חֹלִי וְאִישׁ מַכְאוֹבוֹת עִוֵּר וּפִסֵּחַ צָרוּעַ וְנָגוּעַ דּוֹאֵג וְכוֹאֵב נאכַל לְבַד לְקִיּוּם נַפְשׁוֹתֵינוּ וּלְמַלְאכֵי הַשָּׁרֵת הַנִּפְלָאוֹת בְּאוֹפַנֵּיהֶם הָרַבִּים מַצִּילִים וּמַזִּיקִים עוֹנְשִׁים וּמַשְׂכִּירִים יוֹנְקִים מִכְּבוֹד וּמַלְכוּת הַנְהָגוֹת מַלְכוּת הָעוֹלָם מְמֻנִּים לְכָל מַעֲשֶׂה אֱנוֹשׁ לְמַעְלָה מֵהֶם שְׂרָפִים וְאוֹפַנִּים וְחַיּוֹת הַקּדֶשׁ מַלְכוּת נוֹרָא מַלְכוּת הַכִּסֵּא הֶעָלְמוּ עַד אֵין קֵץ עַד כְּלוֹת הַכֹּל חוּשָׁה עֲנֵנִי ה' רְצֵה מַלְכֵּנוּ בִּתְפִלּוֹתֵינוּ רוּצֵה בְּבָנַיִךְ רוּצֵה בָנוּ`;

